def shape_occurrence_predictions(inp, out, seedcolor, bgzero=0, allow_dihedral=False):
 seed=set(map(tuple,np.argwhere(inp==seedcolor)))
 r0=min(r for r,c in seed); c0=min(c for r,c in seed); seed={(r-r0,c-c0) for r,c in seed}
 def norm(s):
  mr=min(r for r,c in s); mc=min(c for r,c in s); return frozenset((r-mr,c-mc) for r,c in s)
 shapes={norm(seed)}
 if allow_dihedral:
  cur=set(seed)
  for flip in [False,True]:
   for k in range(4):
    pts={(c if flip else r, r if flip else c) for r,c in cur} # bad transform coordinates? 
  # easier D4 all transformations
  shapes=set()
  for trans in range(8):
   pts=set()
   for r,c in seed:
    if trans>=4: c=-c
    for _ in range(trans%4): r,c=c,-r
    pts.add((r,c))
   shapes.add(norm(pts))
 pred=set()
 for s in shapes:
  h=max(r for r,c in s)+1; w=max(c for r,c in s)+1
  for rr in range(inp.shape[0]-h+1):
   for cc in range(inp.shape[1]-w+1):
    cells={(rr+r,cc+c) for r,c in s}
    if all(inp[r,c]==bgzero for r,c in cells): pred |= cells
 actual=set(map(tuple,np.argwhere((inp==bgzero)&(out==seedcolor))))
 print('shape',seed, 'orientations',len(shapes),'pred',len(pred),'actual',len(actual),'match',len(pred&actual), 'miss',len(actual-pred),'extra',len(pred-actual))
 return pred,actual
